-- bhvB3313_13005804  King Bobomb
-- Fixed: no longer uses bobomb_buddy (that soft-locked / made him an NPC).
-- Uses a safe custom setup + vanilla King Bobomb actions when available.
B3313.init[0x13005804] = function(o)
    obj_set_field_s32(o, 0x01, obj_get_field_s32(o, 0x01) | 0x2049)
    b3313_load_anims(o, B3313.data[0x13005804], 0x0500FE30)
    b3313_drop_to_floor(o)
    o.hitboxRadius = 100
    o.hitboxHeight = 100
    o.oHomeX = o.oPosX
    o.oHomeY = o.oPosY
    o.oHomeZ = o.oPosZ
    o.oGravity = 2.5
    o.oFriction = 0.9
    o.oWallHitboxRadius = 100
    -- Grabbable like real King Bobomb (not TEXT/buddy)
    if INTERACT_GRABBABLE then
        o.oInteractType = INTERACT_GRABBABLE
    else
        o.oInteractType = 0x2
    end
    o.oInteractionSubtype = INT_SUBTYPE_GRABS_MARIO or 0
    b3313_animate(o, 0)
    o.oAction = 0
    o.oHealth = 3
end
B3313.loop[0x13005804] = function(o)
    -- Minimal safe King Bobomb-like behavior (no soft lock):
    -- face player, walk toward him, become grabbable.
    local m = nearest_mario_state_to_object(o)
    if m == nil then return end

    cur_obj_update_floor_and_walls()
    obj_turn_toward_object(o, m.marioObj, 0x10, 0x400)

    if o.oAction == 0 then
        -- idle / chase
        o.oForwardVel = 8.0
        cur_obj_move_standard(-78)
        if dist_between_objects(o, m.marioObj) < 250 then
            o.oAction = 1
            o.oTimer = 0
        end
    elseif o.oAction == 1 then
        -- grab attempt window
        o.oForwardVel = 0
        cur_obj_move_standard(-78)
        if o.oTimer > 60 then
            o.oAction = 0
        end
    elseif o.oAction == 2 then
        -- thrown / hit
        cur_obj_move_standard(-78)
        if o.oMoveFlags & OBJ_MOVE_LANDED ~= 0 then
            o.oHealth = o.oHealth - 1
            o.oAction = 0
            if o.oHealth <= 0 then
                -- spawn star if possible, then despawn
                if spawn_default_star then
                    spawn_default_star(o.oPosX, o.oPosY + 200, o.oPosZ)
                end
                obj_mark_for_deletion(o)
            end
        end
    end

    -- If grabbed and thrown by Mario, go to action 2
    if o.oHeldState == HELD_THROWN or o.oHeldState == HELD_DROPPED then
        o.oAction = 2
        o.oHeldState = HELD_FREE
    end
end
bhvB3313_13005804 = hook_behavior(nil, OBJ_LIST_GENACTOR, true, B3313.init[0x13005804], B3313.loop[0x13005804], "bhvB3313_13005804")

